SELECT id, normalized_url AS normalizedUrl, url_hash AS urlHash, domain, title,
site_name AS siteName, summary, source, expires_at AS expiresAt,
created_at AS createdAt, updated_at AS updatedAt
FROM link_card

    AND domain LIKE CONCAT('%', #{domain}, '%')
    AND created_at >= #{from}
    AND created_at < #{to}

ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM link_card

    AND domain LIKE CONCAT('%', #{domain}, '%')
    AND created_at >= #{from}
    AND created_at < #{to}
